// Hand-written `@nestjs/microservices` stub.
//
// `ClientProxy.emit` and `.send` are what the broker adapter matches a
// publisher on, and it insists the receiver's type is declared in this package,
// so the specifier is the load-bearing part.
//
// Both verbs answer with an `Observable`, verified against the real package:
// `send<TResult, TInput>(pattern, data): Observable<TResult>` and
// `emit<TResult, TInput>(pattern, data): Observable<TResult>`. The stub used to
// answer with a bare `R` and a bare `unknown`, which is a different kind of
// type rather than a smaller one: it hid the delivery wrapper that
// `unwrapDelivery` exists to see through, so this fixture was not testing that
// path at all.

import type { Observable } from 'rxjs';

